contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to deposit first so there is a nonzero balance to withdraw
    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract has funds to forward
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // 1) top-level state-changing call: deposit into c so msg.sender (this contract) has a balance
        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // observe before-values for the withdrawal
        uint256 beforeUserBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBalance = address(c).balance;

        // attempt withdrawal and record whether it reverted
        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        uint256 afterUserBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBalance = address(c).balance;

        // If the withdrawal did not revert, then the recorded user balance must be zero
        // and the contract's ETH balance must have decreased by at least the amount that was recorded for this caller before the call.
        // (We allow the contract balance decrease to be >= beforeUserBalance because other callers could have changed balances concurrently in other tests; but in this single-call setting it should be >=.)
        assert(reverted || (afterUserBalance == 0 && beforeContractBalance >= afterContractBalance && beforeContractBalance - afterContractBalance >= beforeUserBalance));
    }

    // receive to accept ETH when c sends funds back
    receive() external payable { }
}

